parameters.text:
=Review the following Jira user story and its Acceptance Criteria for gaps and risks.

Jira Story / Acceptance Criteria:
{{ $json.chatInput }}

parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "verdict": {
      "type": "string",
      "enum": ["Ready", "Not Ready"]
    },
    "overallRiskLevel": {
      "type": "string",
      "enum": ["High", "Medium", "Low"]
    },
    "summary": {
      "type": "string",
      "description": "1-3 sentence overall assessment of the AC quality"
    },
    "gaps": {
      "type": "array",
      "items": {
        "type": "object",
        "properties": {
          "id": { "type": "string" },
          "category": { "type": "string", "enum": ["Ambiguity", "Testability", "Missing Negative/Edge Case"] },
          "severity": { "type": "string", "enum": ["High", "Medium", "Low"] },
          "acReference": { "type": "string" },
          "description": { "type": "string" }
        },
        "required": ["id", "category", "severity", "acReference", "description"]
      }
    }
  },
  "required": ["verdict", "overallRiskLevel", "summary", "gaps"]
}

parameters.text:
=Based on the identified gaps/risks below in a Jira story's Acceptance Criteria, generate targeted clarifying questions for the Product Owner.

Original Story / Acceptance Criteria:
{{ $('When chat message received').item.json.chatInput }}

Overall Verdict: {{ $json.output.verdict }}
Overall Risk Level: {{ $json.output.overallRiskLevel }}

Identified Gaps (JSON):
{{ JSON.stringify($json.output.gaps) }}

parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "questions": {
      "type": "array",
      "items": {
        "type": "object",
        "properties": {
          "id": { "type": "string" },
          "relatedGapId": { "type": "string" },
          "category": { "type": "string" },
          "question": { "type": "string" }
        },
        "required": ["id", "relatedGapId", "category", "question"]
      }
    },
    "note": {
      "type": "string",
      "description": "Optional note, e.g. confirmation when there are no gaps to ask about"
    }
  },
  "required": ["questions"]
}

parameters.jsCode:
const review = $('AC Review & Risk Agent').item.json.output;
const qOut = $input.item.json.output;

const gaps = review.gaps || [];
const questions = qOut.questions || [];

let md = `**Verdict:** ${review.verdict}  \n**Overall Risk Level:** ${review.overallRiskLevel}\n\n**Summary:** ${review.summary}\n\n`;

if (gaps.length === 0) {
  md += `No gaps or risks identified in the Acceptance Criteria.\n`;
} else {
  md += `**Identified Gaps / Risks:**\n`;
  for (const g of gaps) {
    md += `- [${g.id}] (${g.category} / ${g.severity}) ${g.acReference} -> ${g.description}\n`;
  }
  md += `\n**Clarifying Questions:**\n`;
  for (const q of questions) {
    md += `- [${q.id}] (ref ${q.relatedGapId}) ${q.question}\n`;
  }
}

if (qOut.note) {
  md += `\n_Note: ${qOut.note}_\n`;
}

return [{
  json: {
    output: md,
    verdict: review.verdict,
    overallRiskLevel: review.overallRiskLevel,
    summary: review.summary,
    gaps,
    questions,
    note: qOut.note || null
  }
}];
